operation.add:
// [START] Persistent guest cart + throttled garbage collection
//
// headers_sent() is a PRECONDITION, not a late check. If the new cart_hash
// cannot be persisted, the rows must not be moved either - otherwise they end
// up orphaned on a session ID no cookie points to, and the cart silently
// disappears once that session expires.
//
// Note this narrows the window, it does not close it: an HTTP cookie and a SQL
// write cannot be made atomic. Cookie-first breaks the other way if the query
// then fails. So the cookie is written only after a confirmed merge, and the
// residual mismatch is logged rather than pretended away.
if (isset($_COOKIE['cart_hash']) && !$this->customer->isLogged() && !$this->cart_hash_merged && !headers_sent()) {
    $cart_hash       = (string)$_COOKIE['cart_hash'];
    $current_session = $this->session->getId();

    // OpenCart's own session ID format is /^[a-zA-Z0-9,\-]{22,52}$/ (see Session::start()).
    // Validate the raw value - never strip characters, or a legitimate ID gets corrupted
    // and the migration silently matches nothing.
    if (preg_match('/^[a-zA-Z0-9,\-]{22,52}$/D', $cart_hash) && $cart_hash !== $current_session) {
        $this->cart_hash_merged = true;

        $old_sid = $this->db->escape($cart_hash);
        $new_sid = $this->db->escape($current_session);
        $merged  = false;

        try {
            // Cheap indexed probe. A collision needs the destination session to
            // already hold the same product_id + recurring_id + option, which is
            // rare, so the common path stays a single narrow UPDATE.
            //
            // This is a non-locking read and is NOT concurrency safe: a parallel
            // request can insert a colliding row between the probe and the plain
            // UPDATE below. See Known Limitations in the README.
            $collision = $this->db->query("SELECT COUNT(*) AS total FROM " . DB_PREFIX . "cart src INNER JOIN " . DB_PREFIX . "cart dst ON (dst.product_id = src.product_id AND dst.recurring_id = src.recurring_id AND dst.`option` = src.`option`) WHERE src.api_id = '0' AND src.customer_id = '0' AND src.session_id = '" . $old_sid . "' AND dst.api_id = '0' AND dst.customer_id = '0' AND dst.session_id = '" . $new_sid . "'");

            if (!empty($collision->row['total'])) {
                // Aggregate rather than move blindly, otherwise the customer ends
                // up with two identical lines instead of a summed quantity.
                $this->db->query("START TRANSACTION");

                $this->db->query("UPDATE " . DB_PREFIX . "cart dst INNER JOIN " . DB_PREFIX . "cart src ON (dst.product_id = src.product_id AND dst.recurring_id = src.recurring_id AND dst.`option` = src.`option`) SET dst.quantity = dst.quantity + src.quantity, dst.date_added = NOW() WHERE dst.api_id = '0' AND dst.customer_id = '0' AND dst.session_id = '" . $new_sid . "' AND src.api_id = '0' AND src.customer_id = '0' AND src.session_id = '" . $old_sid . "'");

                $this->db->query("DELETE src FROM " . DB_PREFIX . "cart src INNER JOIN " . DB_PREFIX . "cart dst ON (dst.product_id = src.product_id AND dst.recurring_id = src.recurring_id AND dst.`option` = src.`option`) WHERE src.api_id = '0' AND src.customer_id = '0' AND src.session_id = '" . $old_sid . "' AND dst.api_id = '0' AND dst.customer_id = '0' AND dst.session_id = '" . $new_sid . "'");

                $this->db->query("UPDATE " . DB_PREFIX . "cart SET session_id = '" . $new_sid . "', date_added = NOW() WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $old_sid . "'");

                $this->db->query("COMMIT");
            } else {
                // Migrate the session ID AND refresh date_added in one indexed
                // write. GC keys off date_added, so a returning guest resets
                // their own 30-day window at no extra cost.
                $this->db->query("UPDATE " . DB_PREFIX . "cart SET session_id = '" . $new_sid . "', date_added = NOW() WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $old_sid . "'");
            }

            $merged = true;
        } catch (\Exception $e) {
            // Explicit rollback. Relying on connection teardown is unsafe once a
            // retry wrapper or a third-party extension catches the exception.
            try {
                $this->db->query("ROLLBACK");
            } catch (\Exception $ignored) {
                // connection already gone - nothing left to roll back
            }

            // Do not rethrow: a failed cart merge must not take down the
            // storefront. Rows stay on the old session_id and are picked up on
            // a later request, because the cookie is left untouched below.
            // Pin the old cart_hash for the rest of this request. Without this,
            // a set_cart_cookie() call later in the same request would advance the
            // cookie to the current session while the rows are still on the old
            // one - recreating exactly the mismatch this catch block prevents.
            $this->cart_hash_merge_failed = true;

            error_log('cart_cookie_hash: guest cart merge failed, cart_hash pinned to previous session_id - ' . $e->getMessage());
        }

        // Cookie is advanced ONLY after a confirmed merge, so a failed query can
        // never leave the pointer ahead of the data.
        if ($merged && !$this->write_cart_cookie($current_session)) {
            error_log('cart_cookie_hash: cart rows migrated but cart_hash cookie could not be set; cart is reachable for this session only');
        }
    }
}

// Throttled GC: ~0.1% of requests, split queries, bounded by LIMIT so each
// transaction stays short. This reduces lock contention - it does not make
// deadlocks impossible. Keep the retry wrapper in system/library/db/mysqli.php.
if (mt_rand(1, 1000) === 500) {
    $this->db->query("DELETE FROM " . DB_PREFIX . "cart WHERE api_id > '0' AND date_added < DATE_SUB(NOW(), INTERVAL 720 HOUR) LIMIT 200");
    $this->db->query("DELETE FROM " . DB_PREFIX . "cart WHERE api_id = '0' AND customer_id = '0' AND date_added < DATE_SUB(NOW(), INTERVAL 720 HOUR) LIMIT 500");
}
// [END] Persistent guest cart + throttled garbage collection

// Per-instance guard. Cart is constructed once per request in stock OpenCart,
// so this is request-scoped in practice. It does NOT synchronise concurrent
// HTTP requests, and it is not a deadlock mitigation.
private $cart_hash_merged = false;

// Set when the migration threw. While true, set_cart_cookie() must not advance
// the cart_hash cookie, or the pointer would run ahead of the rows that are
// still sitting on the previous session_id.
private $cart_hash_merge_failed = false;

private function get_cookie_params() {
  return [
    'secure' => (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && $_SERVER['HTTP_X_FORWARDED_PROTO'] === 'https'),
    'path'   => !empty(ini_get('session.cookie_path')) ? ini_get('session.cookie_path') : '/',
    'domain' => !empty(ini_get('session.cookie_domain')) ? ini_get('session.cookie_domain') : '',
  ];
}

// Returns the actual setcookie() result. Callers about to move cart rows must
// gate on headers_sent() BEFORE the move; this return value only reports the
// residual failure after the fact, which is a logging concern, not a guarantee.
private function write_cart_cookie($session_id) {
  if (headers_sent()) {
    return false;
  }

  $p       = $this->get_cookie_params();
  $expires = time() + 86400 * 30;

  if (PHP_VERSION_ID >= 70300) {
    $ok = setcookie('cart_hash', $session_id, [
      'expires'  => $expires,
      'path'     => $p['path'],
      'domain'   => $p['domain'],
      'secure'   => $p['secure'],
      'httponly' => true,
      'samesite' => 'Lax',
    ]);
  } else {
    $ok = setcookie('cart_hash', $session_id, $expires, $p['path'], $p['domain'], $p['secure'], true);
  }

  if ($ok) {
    $_COOKIE['cart_hash'] = $session_id;
  }

  return $ok;
}

public function set_cart_cookie() {
  if ($this->customer->isLogged()) {
    return;
  }

  $session_id = $this->session->getId();

  // Preserve the pointer to rows the failed migration left behind. The format check
  // is deliberate: a malformed cart_hash points at nothing and SHOULD be replaced,
  // otherwise garbage would stay pinned for the rest of the request.
  $pin_previous_hash = $this->cart_hash_merge_failed
    && isset($_COOKIE['cart_hash'])
    && $_COOKIE['cart_hash'] !== $session_id
    && preg_match('/^[a-zA-Z0-9,\-]{22,52}$/D', (string)$_COOKIE['cart_hash']);

  if (!$pin_previous_hash && (!isset($_COOKIE['cart_hash']) || $_COOKIE['cart_hash'] !== $session_id)) {
    $this->write_cart_cookie($session_id);
  }

  // Sliding TTL. GC deletes by date_added, but stock add()/update() only change
  // quantity, so an active cart would expire 30 days after the FIRST add. The
  // 24-hour guard means this normally matches zero rows and costs one indexed lookup.
  $this->db->query("UPDATE " . DB_PREFIX . "cart SET date_added = NOW() WHERE api_id = '0' AND customer_id = '0' AND session_id = '" . $this->db->escape($session_id) . "' AND date_added < DATE_SUB(NOW(), INTERVAL 24 HOUR)");
}
